#!/usr/bin/env python3
"""Adelic Persistent Homology — Self-Contained Demo"""

from math import gcd
from itertools import product as cartesian_product

def prime_factors(n):
    if n <= 1: return set()
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1: factors.add(n)
    return factors

def additive_order(element, group_order):
    if group_order <= 0: return 0
    e = element % group_order
    if e == 0: return 1
    for k in range(1, group_order + 1):
        if (k * e) % group_order == 0: return k
    return group_order

def p_primary_nontrivial(group_order, p):
    if group_order <= 1: return False
    for a in range(1, group_order):
        ord_a = additive_order(a, group_order)
        if ord_a <= 1: continue
        while ord_a > 1:
            if ord_a % p != 0: break
            ord_a //= p
        else:
            return True
    return False

def torsion_prime_support(group_order):
    if group_order <= 1: return set()
    return {p for p in prime_factors(group_order) if p_primary_nontrivial(group_order, p)}

class AdelicTorsionDatum:
    def __init__(self, filtration_orders):
        self.n_levels = len(filtration_orders)
        self.orders = filtration_orders
        self.local_supports = {}
        for i, order in enumerate(filtration_orders):
            for p in torsion_prime_support(order):
                self.local_supports[(p, i)] = True

    def reconstruct_support(self, i):
        return {p for (p, j) in self.local_supports if j == i}

    def all_primes(self):
        return {p for (p, _) in self.local_supports}

    def prime_barcode(self, p):
        active = sorted(i for (q, i) in self.local_supports if q == p)
        if not active: return None
        return (active[0], active[-1])

def verify_reconstruction(filtration_orders):
    datum = AdelicTorsionDatum(filtration_orders)
    for i, order in enumerate(filtration_orders):
        if torsion_prime_support(order) != datum.reconstruct_support(i):
            return False, datum
    return True, datum

# === DEMONSTRATIONS ===
print("=" * 60)
print("ADELIC PERSISTENT HOMOLOGY")
print("=" * 60)

print("
--- Example 1: Filtration 0 -> Z/3Z -> Z/6Z ---")
filt = [1, 3, 6]
datum = AdelicTorsionDatum(filt)
for i, order in enumerate(filt):
    d = torsion_prime_support(order)
    r = datum.reconstruct_support(i)
    print(f"  Level {i} (Z/{order}Z): support={d}, reconstructed={r} {'✓' if d==r else '✗'}")
print("  Barcodes:", {p: datum.prime_barcode(p) for p in sorted(datum.all_primes())})

print("
--- Example 2: Z/12Z filtration ---")
filt2 = [1, 2, 4, 12]
datum2 = AdelicTorsionDatum(filt2)
for i, order in enumerate(filt2):
    d = torsion_prime_support(order)
    r = datum2.reconstruct_support(i)
    print(f"  Level {i} (Z/{order}Z): support={d}, reconstructed={r} {'✓' if d==r else '✗'}")
print("  Barcodes:", {p: datum2.prime_barcode(p) for p in sorted(datum2.all_primes())})

print("
--- CRT on Z/6Z: 6 = 2 x 3 ---")
def extended_gcd(a, b):
    if a == 0: return b, 0, 1
    g, x, y = extended_gcd(b % a, a)
    return g, y - (b // a) * x, x
_, u, v = extended_gcd(2, 3)
for a in range(6):
    b = (3 * v * a) % 6
    c = (2 * u * a) % 6
    print(f"  {a} = {b} (2-torsion) + {c} (3-torsion)")

print("
--- Exhaustive test (orders | 60, lengths 3-5) ---")
divs = [d for d in range(1, 61) if 60 % d == 0]
n_tested = n_passed = 0
for length in [3, 4, 5]:
    for combo in cartesian_product(divs, repeat=length):
        if not all(combo[i] <= combo[i+1] and combo[i+1] % combo[i] == 0 for i in range(length-1)):
            continue
        ok, _ = verify_reconstruction(list(combo))
        n_tested += 1
        if ok: n_passed += 1
print(f"  Tested: {n_tested}, Passed: {n_passed}, Failed: {n_tested - n_passed}")
